const rows=[{selector:'.carousel-one',anchor:474,cards:[['大理','dali-video.png',675,508,0],['南高加索·格鲁吉亚','georgia.png',482,642,26],['巴厘岛','bali.png',385,508,0]]},{selector:'.carousel-two',anchor:444,cards:[['平潭','pingtan.png',380,508,34],['海南日记','hainan.png',482,390,0],['创意旅行','creative.png',385,508,34]]}];
window.TRAVEL_CAROUSELS=[];
for(const row of rows){const viewport=document.querySelector(row.selector),track=viewport.firstElementChild;for(let repeat=0;repeat<5;repeat++)for(const [name,file,w,h,top]of row.cards){const card=document.createElement('div');card.className='video-card'+(file==='dali-video.png'?' video-card-dali':'');card.style.cssText=`width:${w/10.8}cqw;height:${h/10.8}cqw;margin-top:${top/10.8}cqw`;const image=document.createElement('img');image.src=`assets/${file}`;image.alt=name+'视频封面';image.draggable=false;card.append(image);track.append(card)}
let cycle=0,timer,drag=null,moved=false,contact=false,idleUntil=0,autoX=null;const measure=()=>{const width=viewport.clientWidth;cycle=(row.cards.reduce((n,c)=>n+c[2],0)+42*3)*width/1080;viewport.scrollLeft=cycle*2+(row.cards[0][2]+42-row.anchor)*width/1080;autoX=null};measure();new ResizeObserver(measure).observe(viewport);
const pauseDrift=()=>{idleUntil=performance.now()+3500;autoX=null};
viewport.addEventListener('pointerdown',()=>{contact=true;pauseDrift()},{passive:true});
const releaseDrift=()=>{contact=false;pauseDrift()};viewport.addEventListener('pointerup',releaseDrift,{passive:true});viewport.addEventListener('pointercancel',releaseDrift,{passive:true});viewport.addEventListener('touchmove',pauseDrift,{passive:true});viewport.addEventListener('wheel',pauseDrift,{passive:true});viewport.addEventListener('keydown',pauseDrift);
window.TRAVEL_CAROUSELS.push({tick(now,dt,modal){const r=viewport.getBoundingClientRect();if(modal||contact||drag||now<idleUntil||r.bottom<0||r.top>innerHeight){autoX=null;return}if(autoX===null)autoX=viewport.scrollLeft;autoX+=(row.selector==='.carousel-one'?1:-1)*4*viewport.clientWidth/540*dt;if(cycle){while(autoX<cycle)autoX+=cycle;while(autoX>=cycle*3)autoX-=cycle}viewport.scrollLeft=autoX}});
function wrap(){if(!cycle)return;let x=viewport.scrollLeft;while(x<cycle)x+=cycle;while(x>=cycle*3)x-=cycle;if(Math.abs(viewport.scrollLeft-x)>1)viewport.scrollLeft=x}
viewport.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(!drag)wrap()},120)},{passive:true});viewport.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;drag={x:e.clientX,left:viewport.scrollLeft};moved=false;viewport.setPointerCapture(e.pointerId)});viewport.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x;if(Math.abs(dx)>4)moved=true;viewport.scrollLeft=drag.left-dx});const end=()=>{drag=null;wrap()};viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);viewport.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();viewport.scrollBy({left:(e.key==='ArrowRight'?1:-1)*viewport.clientWidth*.47,behavior:'smooth'})}});viewport.addEventListener('click',e=>{if(moved)e.preventDefault()});viewport.addEventListener('wheel',e=>{if(Math.abs(e.deltaX)>Math.abs(e.deltaY))return;if(e.shiftKey){e.preventDefault();viewport.scrollLeft+=e.deltaY}},{passive:false})}
